// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn, address actor) public {
        // admissible domain: fresh EOA caller, timestamp strictly past, block divisible by 15
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(0));
        ts = bound(ts, 1, type(uint256).max / 2);
        bn = bound(bn, 15, type(uint256).max - 1);
        vm.assume(bn % 15 == 0);

        vm.warp(ts);
        vm.roll(bn);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // the rule: a winning block call empties the contract
        assertTrue(address(c).balance == 0);
    }
}
